// The upstream BidiClasses.trie bytes are embedded unchanged for Unity/IL2CPP.
namespace Topten.RichTextKit
{
    internal static class UnicodeClasses
    {
        private static readonly UnicodeTrie BidiTrie = new UnicodeTrie(System.Convert.FromBase64String(""));
        public static uint BidiData(int codePoint) => BidiTrie.Get(codePoint);
        public static Directionality Directionality(int codePoint) => (Directionality)(BidiData(codePoint) >> 24);
    }
}